from __future__ import annotations
import base64, hashlib, json, zlib
PAYLOAD_SHA256 = '35777672cd1a23b52864d69523ce504077b604b400fdce8adad2077fe600ac2a'
PAYLOAD_B64 = ''
def load_payload():
    data=json.loads(zlib.decompress(base64.b64decode(PAYLOAD_B64)).decode())
    canon=json.dumps(data,sort_keys=True,separators=(",",":"),ensure_ascii=False).encode()
    got=hashlib.sha256(canon).hexdigest()
    if got != PAYLOAD_SHA256:
        raise RuntimeError(f"sealed payload hash mismatch: {got} != {PAYLOAD_SHA256}")
    return data
